{
  "samples": [
    {
      "scenario_id": "top1_controlled_multiturn_v2_intent_change_travelguide_to_lifeexperience_002",
      "messages": [
        {
          "role": "user",
          "content": "想趁孩子暑假带她去西安玩四天，除了兵马俑和华清宫，还有哪些适合亲子的地方？住在哪个区域比较方便？"
        },
        {
          "role": "assistant",
          "content": "西安亲子游的话，陕西历史博物馆很值得去，但记得提前预约；大唐不夜城晚上逛很热闹，孩子会喜欢。住宿可以选大雁塔附近，去这些景点都方便，地铁也顺。"
        },
        {
          "role": "user",
          "content": "家里那台空气净化器的滤网用了快两年了，是不是该换了？平时怎么判断什么时候要换？"
        }
      ],
      "scenario_summary": "用户先咨询西安亲子游攻略，后直接询问空气净化器滤网更换时机。"
    },
    {
      "scenario_id": "top1_controlled_multiturn_v2_intent_change_fooddiscovery_to_ticketservice_003",
      "messages": [
        {
          "role": "user",
          "content": "这周末想去广州吃早茶，有哪些本地人常去的老字号推荐？"
        },
        {
          "role": "assistant",
          "content": "广州早茶老字号可以试试陶陶居、广州酒家和点都德，不过点都德现在分店多，口味稳定。如果想更地道，去泮溪酒家或者北园酒家，环境也舒服。记得早点去，很多店九点后就排队了。"
        },
        {
          "role": "user",
          "content": "陶陶居的虾饺和红米肠怎么样？两个人大概要多少钱？"
        },
        {
          "role": "assistant",
          "content": "陶陶居的虾饺皮薄馅足，红米肠外层软糯，中间脆皮很香，值得点。两个人如果点五六样点心，大概一百五到两百块，茶位费一般每人十元左右。"
        },
        {
          "role": "user",
          "content": "自己在家做肠粉的话，米浆要怎么调才嫩滑？需要买专门的工具吗？"
        },
        {
          "role": "assistant",
          "content": "家庭版肠粉可以用粘米粉、澄粉和玉米淀粉按大概3:1:0.5的比例调，加适量水搅拌到无颗粒，静置一会儿再蒸。买个家用不锈钢平底蒸盘就行，刷薄油，倒薄浆，旺火蒸一两分钟，这样口感比较嫩滑。"
        },
        {
          "role": "user",
          "content": "帮我查一下今天下午三点左右从广州南站到深圳北站的高铁班次，还有二等座余票情况。"
        }
      ],
      "scenario_summary": "用户先咨询广州早茶餐厅和肠粉做法，后直接查询广州到深圳的高铁票。"
    }
  ]
}

{"samples": [
  {
    "scenario_id": "top1_controlled_multiturn_v2_intent_change_stockother_to_chitchat_001",
    "messages": [
      {
        "role": "user",
        "content": "我账户里目前有两只基金，一只混合型一只指数型，总共投入八万。今天看了一下持仓，显示浮亏六千块，你能帮我算算现在大概值多少钱吗？"
      },
      {
        "role": "assistant",
        "content": "按总投入八万、浮亏六千来算，当前总市值大约是七万四千元。不过这是平台显示的估算值，赎回时还要扣除手续费，实际到账会略有差异。"
      },
      {
        "role": "user",
        "content": "我在研究一家做光伏组件的公司，想了解它除了组件，储能和电站这两个方向占收入的比重怎么样？"
      },
      {
        "role": "assistant",
        "content": "从公开披露看，这家公司光伏组件仍是营收主力，储能和电站业务近两年占比在逐步提升。储能主要贡献增量，电站运维毛利率相对更高，但具体数字建议以最新财报和投资者关系纪要为准。"
      },
      {
        "role": "user",
        "content": "我现在每个月能固定结余三千块，想拿一千五定投黄金ETF，剩下放在货币基金里，这个搭配长期看合适吗？"
      },
      {
        "role": "assistant",
        "content": "黄金ETF和货币基金的风险差异很大。黄金适合做小比例配置来对冲波动，但不是保本资产；货币基金流动性好、收益稳定。按你每月一千五定投黄金，比例占一半偏高，可以先把黄金降到三分之一，留足应急资金再逐步加仓。"
      },
      {
        "role": "user",
        "content": "你平时下班后都喜欢做什么呀？"
      }
    ],
    "scenario_summary": "用户先咨询基金市值、光伏公司研究和定投搭配，最后一轮直接转入日常闲聊。"
  },
  {
    "scenario_id": "top1_controlled_multiturn_v2_progressive_reveal_fooddiscovery_002",
    "messages": [
      {
        "role": "user",
        "content": "明天想在家做一道拿得出手的菜招待朋友，有没有不容易翻车的推荐？"
      },
      {
        "role": "assistant",
        "content": "可以试试可乐鸡翅或者番茄炖牛腩，步骤少、卖相好。如果朋友口味偏清淡，蒜蓉粉丝虾也不错，基本不会失败。"
      },
      {
        "role": "user",
        "content": "朋友更爱吃鱼，我冰箱里有一条鲈鱼，家里有姜、葱和蒸鱼豉油，就是不太会掌握火候，能教我做清蒸鲈鱼的具体步骤吗？"
      },
      {
        "role": "assistant",
        "content": "清蒸鲈鱼关键在火候和去腥：鲈鱼两面划刀，用姜片葱段塞进鱼肚，水开后上锅大火蒸8分钟左右；关火再焖2分钟，倒掉盘中蒸出的水，铺上新葱丝，淋上蒸鱼豉油，最后浇一勺热油激香就可以了。"
      }
    ],
    "scenario_summary": "先问家宴菜品推荐，再具体到清蒸鲈鱼的制作步骤和火候掌握。"
  }
]}

